#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { DIRECTIVE_DEFINITIONS } from '../../src/directives/registry.mjs';
import { allLanguages, SUPPORT_TIERS } from '../../src/lexer/languages.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const TARGET = path.join(ROOT, 'docs', 'directives.md');

export function renderDirectiveDocs() {
  const lines = [
    '# Supported languages and directives',
    '',
    '<!-- Generated by scripts/dev/generate-docs.mjs from src/lexer/languages.mjs and src/directives/registry.mjs. Do not edit by hand. -->',
    '',
    '## Languages',
    '',
    ...Object.entries(SUPPORT_TIERS).map(([tier, description]) => `- **Tier ${tier}**: ${description}`),
    '',
    '| Language | Tier | Extensions and file names |',
    '| :- | :-: | :- |',
    ...allLanguages().map(
      (language) => `| ${language.id} | ${language.tier} | ${[...(language.extensions ?? []), ...(language.filenames ?? [])].map((name) => `\`${name}\``).join(' ')} |`,
    ),
    '',
    'Files with any other extension, and files the lexer cannot tokenize with confidence, are not checked (the hook fails open).',
    '',
    '## Directive families',
    '',
    "A directive is recognized only when it matches the tool's documented grammar. Recognition is separate from authorization: a recognized suppression still goes through the suppression policy (justification, scope, allow and deny lists, documentation-rule protection).",
    '',
    '| Family | Tools | Languages | Reference | Notes |',
    '| :- | :- | :- | :- | :- |',
    ...DIRECTIVE_DEFINITIONS.map(
      (definition) => `| \`${definition.id}\` | ${definition.tool} | ${(definition.families ?? ['all']).join(', ')} | [docs](${definition.url}) | ${definition.activation ?? ''} |`,
    ),
    '',
  ];
  return lines.join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const rendered = renderDirectiveDocs();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(TARGET) ? fs.readFileSync(TARGET, 'utf8') : '';
    if (current !== rendered) {
      console.error('docs/directives.md is out of date; run node scripts/dev/generate-docs.mjs');
      process.exitCode = 1;
    }
  } else {
    fs.mkdirSync(path.dirname(TARGET), { recursive: true });
    fs.writeFileSync(TARGET, rendered);
    console.log(`wrote ${path.relative(ROOT, TARGET)}`);
  }
}
